import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Kernel source for log_softmax (naive per-element)
log_softmax_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

__global__ void log_softmax_kernel(const float* x, const float* out, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        // Placeholder: compute log(exp(x[idx])) - not correct for softmax.
        out[idx] = logf(exp(x[idx]));
    }
}

torch::Tensor log_softmax_cuda(torch::Tensor x) {
    auto size = x.numel();
    auto out = torch::zeros_like(x);

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    log_softmax_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), size);
    return out;
}
"""

# C++ function signature for load_inline
log_softmax_cpp_source = (
    "torch::Tensor log_softmax_cuda(torch::Tensor x);"
)

elementwise_log_softmax = load_inline(
    name="log_softmax",
    cpp_sources=log_softmax_cpp_source,
    cuda_sources=log_softmax_kernel_source,
    functions=["log_softmax_cuda"],
    verbose=True,
    extra_cflags=[],
    extra_ldflags=[]
)

class ModelNew(nn.Module):
    def __init__(self) -> None:
        super().__init__()
        self.log_softmax = elementwise_log_softmax

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.log_softmax(x)
